INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spite & Malice', 'Play North Sky Games’ brand new Spite & Malice game, also known as Skip-Bo and Cat and Mouse. Play all the cards from your payoff piles before your opponent and win the match! With a host of unique game variants, including Kings and Misery, and 4 challenging levels of difficulty, Spite & Malice offers an unparalleled game play experience!' FROM games WHERE igdb_id = 256505 ON CONFLICT (game_id, language_code) DO NOTHING;
