INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meander Forth: Teak''s Tall Tale', 'When aspiring punk-rock drummer Oscar Teak is kicked out of his favorite band, he mopes his way home. He doesn''t get far before he learns some chilling news, however: His childhood friend Tamree Willow is missing! The bearer of this news, a child in a wooden mask, demands that Teak follow her into the woods. Does she really know the whereabouts of the misplaced Ms. Willow? That''s for you to find out.' FROM games WHERE igdb_id = 321297 ON CONFLICT (game_id, language_code) DO NOTHING;
