INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('sketchy-snowboarding', 146939, '2019-07-11', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sc9hfy.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sketchy Snowboarding', 'Sketchy Snowboarding is a hand drawn infinite snowboarder where no two runs are the same. Carve, ollie, grab, grind, and spray folklore beasts to progress through 100 unique challenges. The rules are simple: Carve to the left of red gates. Carve to the right of blue gates. Don''t run into stuff. Send it deep. The "art", sound, and code was created in Colorado and outdoors whenever possible. This project kept me sane during a skateboarding injury in 2018 and I hope you have as much fun playing it as I did making it.' FROM games WHERE igdb_id = 146939 ON CONFLICT (game_id, language_code) DO NOTHING;
