INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Card Monsters: Dungeon', '《卡片地下城Card Monsters: Dungeon》采用DBG+Roguelike的模式，我们把卡牌游戏和Roguelike游戏结合起来，随机性与策略性协调统一，将会给玩家带来全新的游戏体验！招募你所钟爱的英雄，经历种种惊险离奇的事件，构筑独一无二的卡组，打败阻拦你前进的怪物，去征服这片神秘的地下城吧！' FROM games WHERE igdb_id = 119986 ON CONFLICT (game_id, language_code) DO NOTHING;
