INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '真龙主宰', '《真龙主宰》是一款大型多人APRG游戏，游戏中拥有养成、冒险、打斗、社交、互动等各种丰富多样的功能。玩家可以通过点击空白处的方式控制自己的角色，在3D静态地图配合2D动态模型的即时光影成像技术下与怪物战斗，和兄弟结盟，挥洒热血，激战沙场。在服务器架构上支持多服务器动态支撑技术，能容纳数万玩家在游戏内娱乐。游戏美术设计上汲取了东西方的美术元素，使用玄幻而写实的美术风格，人物造型华丽而独特，富有真实立体效果和绚丽的光影。' FROM games WHERE igdb_id = 128301 ON CONFLICT (game_id, language_code) DO NOTHING;
