INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ten Days', 'Ten Days is a small game about a young man'' life in city. He need to save himself in ten days by make a game or find a job or whatever could save him. You will make many choice , go through lots of stories to make it happen . It is easy to play, Most time you just move and click your mouse.' FROM games WHERE igdb_id = 120145 ON CONFLICT (game_id, language_code) DO NOTHING;
