INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('protect-and-defense-tank-attack', 145154, '2019-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2wer.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc96gs.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Protect & Defense: Tank Attack', 'Strategy genre Tower Defense. Here you will fight against numerous enemies, defending their zone. Take control of the most powerful towers to stop tanks, airplanes, ships and other equipment. Expand your influence zone on huge maps and correctly arrange turrets and towers. Try to win this intense war, using different strategies, as well as relying on your skill and tactical skills. Remember that in this game every battle is like a royal battle! Your towers are not toys! They are ready to erase every alien! 
