INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Black Rose', 'The Black Rose is a first person, psychological horror experience. The player is invited out on a date to the Black Rose bar, however once inside they soon discover that something is terribly wrong. Explore the nature of the Black Rose and venture deep into its belly. Interact with objects and find hidden notes left behind in order to discover the dark truth; the further in you go, the more secrets you will uncover. You are not as innocent as you may think...' FROM games WHERE igdb_id = 124260 ON CONFLICT (game_id, language_code) DO NOTHING;
