INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zozzled', 'Hotsy-totsy! It''s 1928 and you''re madcap flapper Hazel Greene, tottering around the city''s finest hotel with a gullet full of giggle juice...until a gaggle of ghosts shows up to spoil the fun by turning every drop in the place into lousy, undrinkable WATER. Explore the beautiful Poseidon Grand Hotel, meet Barnaby Mooch the Magnificent Pooch, and get splifficated on a snootful of ectoplasm in this paranormal puzzle comedy.' FROM games WHERE igdb_id = 139735 ON CONFLICT (game_id, language_code) DO NOTHING;
