INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jewels Palace', 'Jewel Palace is the sequel to the mobile puzzle game Jewel Fantasy, a mobile game where you match 3 jewels of the same kind to progress through stages. Due to the simple concept of the game, it can be played by everyone, anywhere, at any time, with amazing graphics and a unique system that shifts gravitation, all topped off with a mysterious world map to provide endless hours of fun.' FROM games WHERE igdb_id = 114757 ON CONFLICT (game_id, language_code) DO NOTHING;
