INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F1 2019: Legends Edition', 'Fans who purchase the ‘F1 2019 Legends Edition’ will get to drive as Ayrton Senna in his 1990 McLaren MP4/5B and Alain Prost in the Ferrari F1-90, face-off over eight race challenges, and receive exclusive Senna and Prost themed multiplayer car liveries. The drivers’ likenesses have also been added to the Career mode which players can experience when this edition is launched with three days early access on June 25th 2019 on PlayStation4 computer entertainment system, the Xbox One family of devices including the Xbox One X and Windows PC (DVD and via Steam).' FROM games WHERE igdb_id = 125192 ON CONFLICT (game_id, language_code) DO NOTHING;
