INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operator 41', 'Help your Operator reach the telephone to call headquarters with vital intel. Vigilant guards patrol the grounds, and security cameras keep a watchful gaze. Use stealth to sneak by them. Throw objects you’ll find to distract the guards, or even knock them out – but aim and timing is everything. Operator 41 is all about sneakiness and strategy.' FROM games WHERE igdb_id = 125511 ON CONFLICT (game_id, language_code) DO NOTHING;
