INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('my-sweet-stepsisters', 205896, '2019-08-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4wbo.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schkp7.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'My Sweet Stepsisters', 'You were living an average life as a college student with your mom and dad when suddenly, your dad makes the shocking confession that he’s actually your stepdad… and that he has three daughters he never told you about! Their mother has gone missing, so now you’re suddenly forced to live with your new stepsisters! Your mom is not pleased and you’re definitely confused… but you start to adjust to life with them. As you work to help them solve their own issues, you begin to realize that there might be something sinister about the disappearance of their mother. You also begin to wonder whether it’s okay to fall in love with them… What will you do?!' FROM games WHERE igdb_id = 205896 ON CONFLICT (game_id, language_code) DO NOTHING;
