INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('love-is-a-canvas', 210315, '2019-07-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4zy8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/schy49.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love is a Canvas', 'After being accused of plagiarism, you thought your career as an artist was over. No matter how much your beautiful artist friend tries to convince you, you just can''t get yourself to display your work… But one day, you decide to paint the girl of your dreams on a blank canvas and before you know it… she appears at your door! It seems like everything you paint about her seems to come true! Could you really have brought her life just by painting her? With a new sense of courage, you reenter the gallery scene where you meet an up and coming new artist that encourages you more! But as you paint more and more, you begin to wonder if this girl really is the girl that you painted… Is your true love nothing more than a figment of your imagination? Or could she be more real than you could ever imagine?' FROM games WHERE igdb_id = 210315 ON CONFLICT (game_id, language_code) DO NOTHING;
