INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Here Be Dragons', 'Here Be Dragons is a satirical turn-based strategy game featuring unique "living map" graphics, where you lead a group of crazed captains and eradicate legendary monsters in order to allow Christopher Columbus the discovery of the New World.' FROM games WHERE igdb_id = 110355 ON CONFLICT (game_id, language_code) DO NOTHING;
