INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Story About Times', '时间是我们唯一不能抵抗的东西 有些人和事一旦失去就永远也找不回来了吧 在钢筋水泥构建的世界中 人们疲惫的奔跑 徘徊 哭泣 大笑 又瞬间淹没于茫茫人海 昏暗的环境 孤独的行走着的人 回头的一瞬间 别忘了我们的来处！' FROM games WHERE igdb_id = 113009 ON CONFLICT (game_id, language_code) DO NOTHING;
