INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('left-right-the-mansion', 114202, '2019-01-17', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5aj9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arc36.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Left-Right: The Mansion', 'Left-Right: The Mansion is a little game about a boy, Billy, whose dog named Gigi ran away inside a big mansion. He must journey through this mysterious place, where he will have to find and remember the right path in order to find her. Every room will challenge him with a simple choice to make: left or right. Two doors, yet only one will make him go forward; the other one will bring him back to the beginning. Left-Right is a memory game filled with strange creatures and scary bosses who will try to stop Billy from finding his dog. It is a pretty simple and fun 2D game inspired by the old classic games, for which, even after all these years, we still remember the button sequences to avoid the punches or get 30 lives. The human memory is a very fascinating thing, and Left-Right is here to test its limits. Will you be able to help Billy find Gigi? Or will she be trapped forever in this crazy mansion? Enjoy!' FROM games WHERE igdb_id = 114202 ON CONFLICT (game_id, language_code) DO NOTHING;
