INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('please-dont-touch-anything-classic', 151565, '2019-06-13', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/arba5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Please, Don''t Touch Anything: Classic', 'Please, Don’t Touch Anything: Classic is a pixelated, brain-racking, button-pushing puzzle game. Covering for a colleague taking a bathroom break, you find yourself in front of a mysterious panel with a green screen monitor above it showing a blurry live image of an unknown city. Also present is an ominous red button with the simple instruction to not touch anything! Push the red button once or press it many times. Your choices and actions will lead to outrageous consequences and 25 unique puzzle endings. Scavenge for clues, tools, and buttons to solve riddles and trigger explosive events. This deceptively simple console has many mind-blowing surprises for you. Go ahead, press the button. You know you want to.' FROM games WHERE igdb_id = 151565 ON CONFLICT (game_id, language_code) DO NOTHING;
