INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cities: Skylines - Parklife Edition', 'Cities: Skylines is a modern take on the classic city simulation. The game introduces new gameplay elements to realize the thrill and hardships of creating and maintaining a real city whilst expanding on some well-established tropes of the city building experience. Constructing your city from the ground up is easy to learn, but hard to master.' FROM games WHERE igdb_id = 205268 ON CONFLICT (game_id, language_code) DO NOTHING;
