INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grandpa And Granny Home Escape', 'Grandpa And Granny House Escape is a horror game where you will be chased by an insane grandpa and a scary granny. Oh, they adore playing hide-and-seek. Surely, it is not an ordinary hide-and-seek fun – but a tough survival experience. Grandpa and granny always find a new victim to play their cruel game of survival. Your escape will not be easy because granny and grandpa are very experienced hunters.' FROM games WHERE igdb_id = 248177 ON CONFLICT (game_id, language_code) DO NOTHING;
