INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Color.Motif Deluxe', 'New, polished, relaxing, artistic puzzle game with lots of motifs and various difficulty. Color.Motif Deluxe is an artistic puzzle game. It is a sequel of previous game award-winning "Motif. Relaxing puzzle environment, create your color-motif with given pieces. Features: • 512 beautifully hand-crafted motif levels • 4 level season and gameplay challenge • Mixed gameplay challenge for hardcore players • 3 different hint type • Beautifully crafted artistic puzzle game' FROM games WHERE igdb_id = 126198 ON CONFLICT (game_id, language_code) DO NOTHING;
