INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '12 Locks: Plasticine Room', '12 Locks: Plasticine Room is an online puzzle game that challenges players to use their puzzle-solving skills to unlock 12 different locks to complete the game. The game is set in a plasticine room, where players must navigate their way through the challenges to unlock each lock. The puzzles require players to think creatively and logically, using their problem-solving skills to overcome each obstacle in their path. With each lock unlocked, players gain a sense of satisfaction and progress toward completing the game.' FROM games WHERE igdb_id = 308527 ON CONFLICT (game_id, language_code) DO NOTHING;
