INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cities: Skylines - Premium Edition 2', 'Bundle up, builders! The Cities: Skylines - Premium Edition 2 for consoles has everything you need to take your city-planning skills to new heights. Along with the base game, this bundle includes Season Pass 2, which will launch with Green Cities and European Suburbia in January 2019, and continue to deliver some of the game''s most popular content add-ons throughout the year.' FROM games WHERE igdb_id = 119080 ON CONFLICT (game_id, language_code) DO NOTHING;
