INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apocryph: an old-school shooter', 'Apocryph is a FPS set in a brutal dark fantasy world. It takes it''s roots in old-school fantasy shooters, so prepare for intense sword-and-sorcery FPS action amidst forgotten castles, evil shrines and decrepit dungeons! The world of Apocryph is a grim, violent place, harboring magic, dark rituals and dangers around every corner. Wherever you go you''ll be facing unrelenting monsters, traps and locked passages, and can only depend on yourself and your equipment to survive the trials.' FROM games WHERE igdb_id = 117926 ON CONFLICT (game_id, language_code) DO NOTHING;
