INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mystery Case Files: Key to Ravenhearst', 'Mystery Case Files: Key to Ravenhearst is the twelfth installment of the Mystery Case Files franchise and is the first to be developed by Eipix Entertainment. Key to Ravenhearst was released on October 27, 2015. Key to Ravenhearst will be the third instance the series has returned to the Ravenhearst storyline, thus the fourth installment in the Ravenhearst story-arc.' FROM games WHERE igdb_id = 50238 ON CONFLICT (game_id, language_code) DO NOTHING;
