INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hoop League Tactics', 'Hoop League Tactics is a fresh new take on the sports management simulation genre. Take control of your basketball team and lead them to victory in turn-based tactical action. Manage your players between games by upgrading their skills and scouting for the next prospect to join your squad. Whether you''d rather control every action or watch from the sidelines, how you decide to play the game is entirely up to you!' FROM games WHERE igdb_id = 237604 ON CONFLICT (game_id, language_code) DO NOTHING;
