INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Peepaw', 'Oh no! Peepaw was messing around with the Ouija board and got possessed again! Help find Meemaw and escape! That''s right, your good ol'' grandpa has been possessed by demonic forces and is now attempting to murder you and your family! Traverse a dark house, find your cousins for upgrades, and rescue Meemaw before you''re all dragged to Hell! This version features new Peepaw behaviors.' FROM games WHERE igdb_id = 134868 ON CONFLICT (game_id, language_code) DO NOTHING;
