INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lily''s Garden', 'Get your hands dirty in Lily’s Garden, our new FREE puzzle game! Help Lily restore her great-aunt’s garden to its former glory and rediscover her roots. Dig into a story full of twists and turns as Lily interacts with a cast of colorful characters. Plant the seed of romance with her handsome neighbor Luke, and keep her rake of an ex-boyfriend Blaine off her turf. Match and collect flowers in hundreds of unique puzzle levels to earn stars and grow your garden!' FROM games WHERE igdb_id = 129160 ON CONFLICT (game_id, language_code) DO NOTHING;
