INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yucatan', 'Yucatan is a fast-paced, fake-mexican, space-punk driving experience. It''s a 3D racing game, with metroidvania elements. You unlock abilities and use them to unlock new areas and new tracks. There''s a cast of fun characters, and a cool story (bro). But most of all it has amazing handling, exceptional drifting, some serious jumps, and you can drive upside down.' FROM games WHERE igdb_id = 113443 ON CONFLICT (game_id, language_code) DO NOTHING;
