INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('cinderella-an-interactive-fairytale', 114183, '2019-01-18', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co57a8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arbb6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cinderella: An Interactive Fairytale', 'Explore the magical world she lives in, feed pigeons, bond with the castle''s watchdog (a noble Pomeranian) and save the prince in this little adventure for fairytale enthusiasts of all ages! Enjoy a relatable and diverse mix of characters who prove that being beautiful is not about fulfilling common, unattainable ideals of beauty. In addition to the interactive story and its puzzles, some mini-games are also included and seamlessly incorporated into the narration. Tired of being hassled by ads and in-game-purchase offers? So are we, which is why you will find neither in this game. Another thing you won''t find in this game are external links and violence. All of this makes the game also suitable for children of a young age, especially since the professional voice actors Sky du Mont, Lisa Pitt and Geoffrey Steinherz lend their amazing voices to the narrator and the characters, so the story can be enjoyed even without being able to read.' FROM games WHERE igdb_id = 114183 ON CONFLICT (game_id, language_code) DO NOTHING;
