INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Block in the Lock', 'Block in the Lock is a 2D puzzle game where you move different blocks simultaneously like a hive mind. These blocks can be shifted and shaped to create certain patterns. All blocks move at the same time in the same direction and interact with their environment. A puzzle is solved when the movable blocks fill out the required shape with a certain pattern.' FROM games WHERE igdb_id = 297690 ON CONFLICT (game_id, language_code) DO NOTHING;
