INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Double Symbol', 'It is a card game in which all of the cards are laid face down on a surface and two cards are flipped face up over each turn. The object of the game is to turn over pairs of matching cards. It is a particularly good game for young children, though adults may find it challenging and stimulating as well. The scheme is often used in quiz shows and can be employed as an educational game.' FROM games WHERE igdb_id = 267564 ON CONFLICT (game_id, language_code) DO NOTHING;
