INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nice Bowling', 'Nice Bowling is an unfair bowling game modeled after the late 80''s, early 90''s obsession with chrome and neon, Nice Bowling''s unique look and retrowave/chillwave soundtrack will really bring you back. Random events can trigger on any frame of play to a huge variety of outcomes- good luck bowling with a beach ball, a jelly blob, or a bouncy ball. Sometimes fish rain from the sky and block the lane. Sometimes there will be obstacles or ramps in your path.' FROM games WHERE igdb_id = 129953 ON CONFLICT (game_id, language_code) DO NOTHING;
