INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brick Breaker Dungeon', 'Brick Breaker Dungeon is a brick breaker pinball arcade game. To play it you should bounce balls from walls and destroy magic blocks that descend every turn. Different blocks have unique properties that can be used against them. Choose the right angle to fire pinballs, use the best spells and strike evil blocks to destroy them and get a reward!' FROM games WHERE igdb_id = 256458 ON CONFLICT (game_id, language_code) DO NOTHING;
