INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crawlco Block Knockers', 'Return to the feel of smokey ‘90s Japanese arcades as you pull, kick and match blocks to reveal hidden images of the lovely ladies behind each stage! As blocks enter the play field, knock them into marked zones while avoiding and smashing enemies, all as your workspace gets tighter. Aim carefully to boost your score, but don’t get boxed in!' FROM games WHERE igdb_id = 144623 ON CONFLICT (game_id, language_code) DO NOTHING;
