INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chess Royale', 'Whether you’re a complete beginner or a highly experienced player, Chess Royale has everything you could need to enjoy one of the world’s greatest board games on your mobile device. Play with the AI, with friends, or with millions of strangers all over the world, then train your chess skills with tutorials, puzzles, and post-game analysis. One of the greatest things about chess is that there’s always something new to learn, and this beautifully designed app will allow you to keep on discovering the magic of chess and enhancing your love of the game day after day.' FROM games WHERE igdb_id = 330918 ON CONFLICT (game_id, language_code) DO NOTHING;
