INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dreadful Tales: The Fire Within - Collector''s Edition', 'When Jill and Josh Weaver take their daughter on a relaxing hike, they’re hoping for photo opportunities and family bonding, but they get more excitement than they bargained for as disturbing messages and menacing pranks escalate into physical threats. Soon Jill is all alone, stalked by a terrifying figure wielding a flamethrower. With the fog closing in and her family still missing, it becomes clear that her nightmare has only just begun! Can you reunite Jill’s family and uncover the secret of Coldfell Forest’s dark past? Find out in this thrilling hidden object puzzle adventure!' FROM games WHERE igdb_id = 222013 ON CONFLICT (game_id, language_code) DO NOTHING;
