INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '8-BIT Yu-No''s Great Adventure', 'A side-scrolling action game developed by Platine Dispotif and MAGES for the nintendo Switch, 8-bit Yu-no''s Great adventure is a spinoff of Yu-No A girl that chants love at the bounds of this world released alongside it''s 2019 remake for the Nintendo Switch. Playing as Yu-No, the game adapts the Adapts the ADaMS system from the visual novel allowing for the player to rewind the game to follow different routes in order to attain key items to reach the final stage and boss.' FROM games WHERE igdb_id = 209737 ON CONFLICT (game_id, language_code) DO NOTHING;
