INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Saint Seiya: Awakening', 'Saint Seiya: Awakening is a mobile game masterpiece which perfectly restores the classic feeling of the Japanese comics. 12 Golden Saints and all classic characters are back to the Sanctuary and waiting for your summoning. Set up your exclusive team and work on your strategy to win! In addition to beautiful game graphics and cool combat effects, you can enjoy Japanese voice acting along with the classic theme songs.' FROM games WHERE igdb_id = 122667 ON CONFLICT (game_id, language_code) DO NOTHING;
