INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aerial Life', 'The protagonist is a part-time beta tester at a game developer company that runs the popular virtual reality game Aerial Life. However, there was an unknown bug after the latest major update and he became trapped in the virtual reality world, along with fellow beta-tester Otome, who lost her memories of the outer world. Unable to log out, they had to stay in the virtual world for a while and complete the grand quest. Will he be able to recover her memories and break free from the game?' FROM games WHERE igdb_id = 147445 ON CONFLICT (game_id, language_code) DO NOTHING;
