INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Novel Collector (Speedrun Edition)', 'Super Novel Collector is a 2D Platform game built for speedrunning. It features an inbuilt timing and split system. It can also be played casually and with a random level generator. Xander, a descendant of the last librarian of Alexandria, seeks to correct the error of his ancestor and restore the library.' FROM games WHERE igdb_id = 126883 ON CONFLICT (game_id, language_code) DO NOTHING;
