INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barry Bradford''s Putt Panic Party', 'Tee off with up to three friends simultaneously for maximum fun! You have a limited time to aim your shot and the timer gets shorter every turn! It’s a party of putting with panic guaranteed. - Party and Single modes. - Three difficulty settings. - Forward and reverse holes. - Four unique courses. - Loads of wacky hazards. Bring your friends, select your characters and get ready to Putt Panic Party all night long with the world''s greatest Putt Panic Party Player, Barry Bradford!' FROM games WHERE igdb_id = 122865 ON CONFLICT (game_id, language_code) DO NOTHING;
