INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-street-racer', 124066, '2019-11-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4p2b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/aralr.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Street Racer', 'A NEW ERA OF STREET RACING STARTS NOW In Super Street: Racer, you don’t just buy your car, you build it. Use hundreds of car parts from the biggest aftermarket brands to customize your exterior, interior and performance to go from scrap to supercar! Take your build to the streets and tear up the roads in breathtaking landscapes or world cities. From drifting on the highways in Tokyo and burning rubber in the Nevada desert, to cruising the warm, atmospheric streets of Los Angeles. Super Street: Racer is officially licensed by MotorTrend Group, the largest automotive media brand in the world. It is supported by the biggest car enthusiast communities in car tuning, such as Super Street, Hot Import Nights and Speed Society. This is the ultimate street racing experience! FEATURES: • Intense action-packed racing pushing your car to its very limits! • Go from scrap to supercar, building your ultimate street racer! • Extensive and authentic customization: tune your car using 500+ branded aftermarket car parts among them Continental, JBL, Falken, BBS and Sparco. • Play through a career mode featuring over 60 missions divided over rich and vibrant worlds ranging from world cities to outdoor environments. • Take it up against friends and family in split-screen!' FROM games WHERE igdb_id = 124066 ON CONFLICT (game_id, language_code) DO NOTHING;
