INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mahjong Stories: Vampire Romance', 'For many years Edward suffered from insomnia and saw what others did not. One day he tried to escape all the nightmares but his evil destiny overtook him near the weird graveyard. Its unhappy souls suffered under the authority of the cruel ancient vampire, and their last hope was the Savior, brave and clever enough to solve all the mysteries and break the cursed seals. So Edward decided to stay and challenge Count Orlok…' FROM games WHERE igdb_id = 115874 ON CONFLICT (game_id, language_code) DO NOTHING;
