INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Original Mobile Games', 'The Original Mobile Games collection puts 149 years of playable game history into the hands of game enthusiasts around the world! The game features playable digital reproductions of historic dexterity games and puzzles, complete with original art, photographs and background information for each game straight from the archives of the Strong National Museum of Play in Rochester, NY.' FROM games WHERE igdb_id = 130882 ON CONFLICT (game_id, language_code) DO NOTHING;
