INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow Codex', 'Battle against an evil force in this unique word/RPG hybrid game! Face off against countless enemies in turn-based combat by mastering words, spells, weapons, and items. Explore an ever-unfolding map with characters to meet, stories to tell, and quests to embark upon. Earn gold and visit shops to upgrade your equipment and buy items. Earn experience to level up and improve your character''s fighting stats in combat.' FROM games WHERE igdb_id = 175153 ON CONFLICT (game_id, language_code) DO NOTHING;
