INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shopping Clutter 3: Blooming Tale', 'The Walkers, the traveling animal family well-known to fans of the Travel Mosaic series, have decided to help Auntie Sheep decorate her flower shop. After moving to Animalville, Auntie Sheep noticed there weren’t enough plants hanging from the balconies of the apartment buildings and decided to open a flower shop. But decorating isn’t as easy as it looks, and the Walkers are here to help! Clear the clutter from the store shelves and find all the necessary flowers and equipment.' FROM games WHERE igdb_id = 215031 ON CONFLICT (game_id, language_code) DO NOTHING;
