INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nanoswarm', 'Nanoswarm is a game about surviving an endless assault from an army of nanobots with the ability to form terrifying and unstoppable battlebots. You''re not alone though. Tank command is back at base finding you new powerups all the time, helping you to overcome the odds and have a chance against your terrible foe.' FROM games WHERE igdb_id = 110971 ON CONFLICT (game_id, language_code) DO NOTHING;
